import{_ as e,o as s,c as a,a2 as i}from"./chunks/framework.C8822HRV.js";const g=JSON.parse('{"title":"Spec-Driven Development CLI tutorial (10 minutes)","description":"Install the sdd Spec-Driven Development CLI, run your first AI-friendly change pack, and finish a local loop—intent in git, not only in chat. Beginner tutorial.","frontmatter":{"title":"Spec-Driven Development CLI tutorial (10 minutes)","description":"Install the sdd Spec-Driven Development CLI, run your first AI-friendly change pack, and finish a local loop—intent in git, not only in chat. Beginner tutorial.","head":[["meta",{"property":"og:title","content":"Spec-Driven Development CLI tutorial (10 minutes) · sdd"}],["meta",{"property":"og:description","content":"Install the sdd Spec-Driven Development CLI, run your first AI-friendly change pack, and finish a local loop—intent in git, not only in chat. Beginner tutorial."}],["meta",{"property":"og:url","content":"https://harsha09.github.io/spec-driven-development/tutorials/first-change/"}],["meta",{"property":"og:image","content":"https://harsha09.github.io/spec-driven-development/og.jpg"}],["meta",{"name":"twitter:title","content":"Spec-Driven Development CLI tutorial (10 minutes) · sdd"}],["meta",{"name":"twitter:description","content":"Install the sdd Spec-Driven Development CLI, run your first AI-friendly change pack, and finish a local loop—intent in git, not only in chat. Beginner tutorial."}],["meta",{"name":"twitter:image","content":"https://harsha09.github.io/spec-driven-development/og.jpg"}],["link",{"rel":"canonical","href":"https://harsha09.github.io/spec-driven-development/tutorials/first-change/"}]]},"headers":[],"relativePath":"tutorials/first-change.md","filePath":"tutorials/first-change.md","lastUpdated":1785895617000}'),n={name:"tutorials/first-change.md"};function d(o,t,l,r,p,h){return s(),a("div",null,[...t[0]||(t[0]=[i(`<h1 id="spec-driven-development-cli-start-in-10-minutes" tabindex="-1">Spec-Driven Development CLI: start in 10 minutes <a class="header-anchor" href="#spec-driven-development-cli-start-in-10-minutes" aria-label="Permalink to &quot;Spec-Driven Development CLI: start in 10 minutes&quot;">​</a></h1><p>This tutorial is the fastest way to learn <strong>sdd</strong>, a <strong>local Spec-Driven Development CLI</strong> for <strong>AI coding agents</strong>. You’ll make a tiny change pack, write a few sentences <strong>in the repo</strong>, and finish. No enterprise process. No long theory.</p><p>By the end, intent and progress live as <strong>markdown in git</strong>—the same trail you and Copilot, Claude Code, Grok, or Ollama can share.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Time</strong></td><td>About 10 minutes</td></tr><tr><td><strong>You need</strong></td><td>Node.js 20+ and a folder for an app (or an empty folder)</td></tr><tr><td><strong>Goal</strong></td><td>Feel the loop: start → write a note → next → finish</td></tr><tr><td><strong>Install</strong></td><td><a href="https://www.npmjs.com/package/@structured-vibe-coding/cli" target="_blank" rel="noreferrer"><code>@structured-vibe-coding/cli</code></a> on npm</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Stay calm</p><p>We’ll use <code>--no-agent</code> so nothing launches an AI window while you learn. You can turn the agent on later.</p></div><div class="info custom-block"><p class="custom-block-title">Other paths</p><p>New product? → <a href="./../guides/greenfield">Greenfield</a><br> Bigger feature? → <a href="./../guides/simple-feature">Simple feature</a> after this tutorial</p></div><hr><h2 id="step-1-—-install" tabindex="-1">Step 1 — Install <a class="header-anchor" href="#step-1-—-install" aria-label="Permalink to &quot;Step 1 — Install&quot;">​</a></h2><p>Package on npm: <strong><a href="https://www.npmjs.com/package/@structured-vibe-coding/cli" target="_blank" rel="noreferrer">@structured-vibe-coding/cli</a></strong></p><p><strong>Easiest (recommended):</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @structured-vibe-coding/cli</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sdd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span></code></pre></div><p><strong>Or without a global install:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @structured-vibe-coding/cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span></code></pre></div><p>If you use <code>npx</code>, put <code>npx @structured-vibe-coding/cli</code> wherever you see <code>sdd</code> below.</p><details><summary>Building from this GitHub repo instead?</summary><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/harsha09/spec-driven-development.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> spec-driven-development</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">corepack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">corepack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prepare</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pnpm@9.15.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --activate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @structured-vibe-coding/cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> link</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sdd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span></code></pre></div></details><hr><h2 id="step-2-—-go-to-your-app" tabindex="-1">Step 2 — Go to your app <a class="header-anchor" href="#step-2-—-go-to-your-app" aria-label="Permalink to &quot;Step 2 — Go to your app&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/projects/my-app</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># or: mkdir demo-app &amp;&amp; cd demo-app</span></span></code></pre></div><p><code>sdd</code> lives <strong>next to</strong> your code. It doesn’t replace React, Python, etc.</p><hr><h2 id="step-3-—-one-time-setup" tabindex="-1">Step 3 — One-time setup <a class="header-anchor" href="#step-3-—-one-time-setup" aria-label="Permalink to &quot;Step 3 — One-time setup&quot;">​</a></h2><p>Pick <strong>one</strong> AI tool (you can change later):</p><table tabindex="0"><thead><tr><th>If you use…</th><th>Run</th></tr></thead><tbody><tr><td>GitHub Copilot</td><td><code>sdd init --here --ai copilot</code></td></tr><tr><td>Grok</td><td><code>sdd init --here --ai grok</code></td></tr><tr><td>Claude Code</td><td><code>sdd init --here --ai claude</code></td></tr><tr><td>Ollama (local)</td><td><code>sdd init --here --ai ollama</code> then <code>ollama pull llama3.2</code></td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sdd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --here</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ai</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> copilot</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sdd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span></code></pre></div><p>You want green checks from <code>sdd doctor</code>. After init you should see folders like <code>.sdd/</code>, <code>memory/</code>, and <code>changes/</code>.</p><hr><h2 id="step-4-—-start-a-tiny-change" tabindex="-1">Step 4 — Start a tiny change <a class="header-anchor" href="#step-4-—-start-a-tiny-change" aria-label="Permalink to &quot;Step 4 — Start a tiny change&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sdd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Fix empty list crash&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -w</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hotfix</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-agent</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Flag</th><th>Why</th></tr></thead><tbody><tr><td><code>-w hotfix</code></td><td>Shortest path (great for learning)</td></tr><tr><td><code>-y</code></td><td>Don’t ask extra questions</td></tr><tr><td><code>--no-agent</code></td><td>Don’t open the AI yet</td></tr></tbody></table><p>The tool prints a path to a file. That’s your <strong>intent</strong> file — the short note for this work.</p><p>Check where you are anytime:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sdd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><p>You should see something like:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Stage:    intent</span></span>
<span class="line"><span>[●] intent</span></span>
<span class="line"><span>[ ] implement</span></span>
<span class="line"><span>[ ] local_verify</span></span></code></pre></div><hr><h2 id="step-5-—-write-a-few-real-sentences" tabindex="-1">Step 5 — Write a few real sentences <a class="header-anchor" href="#step-5-—-write-a-few-real-sentences" aria-label="Permalink to &quot;Step 5 — Write a few real sentences&quot;">​</a></h2><p>Open <code>intent.md</code> under <code>changes/&lt;something&gt;/</code> and <strong>replace</strong> the template with:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Intent</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Empty expenses list crashes the page with a null reference.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Fix: show an empty state when there are zero rows instead of throwing.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Success: open expenses with no data — no error, empty state UI visible.</span></span></code></pre></div><p>That’s enough. Empty templates block the next step on purpose — so the note is real, not a placeholder.</p><hr><h2 id="step-6-—-move-forward-and-finish" tabindex="-1">Step 6 — Move forward and finish <a class="header-anchor" href="#step-6-—-move-forward-and-finish" aria-label="Permalink to &quot;Step 6 — Move forward and finish&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sdd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> next</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-agent</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># stage is now &quot;implement&quot; — fix the bug (or skip real code in a demo folder)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sdd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> next</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-agent</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sdd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> complete</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-agent</span></span></code></pre></div><p><strong>You’re done when</strong> <code>sdd status</code> no longer shows this as the active in-progress work (or the change’s status is completed).</p><hr><h2 id="if-something-goes-wrong" tabindex="-1">If something goes wrong <a class="header-anchor" href="#if-something-goes-wrong" aria-label="Permalink to &quot;If something goes wrong&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What you see</th><th>What to do</th></tr></thead><tbody><tr><td><code>sdd: command not found</code></td><td>Install again, or use <code>npx @structured-vibe-coding/cli …</code></td></tr><tr><td><code>next</code> says the file is incomplete</td><td>Paste the sample intent above into <code>intent.md</code></td></tr><tr><td>Unsure if setup is OK</td><td>Run <code>sdd doctor</code></td></tr><tr><td>Want a different AI</td><td><code>sdd agents install --ai grok --force</code> (or copilot / claude / ollama)</td></tr></tbody></table><hr><h2 id="what-you-just-learned" tabindex="-1">What you just learned <a class="header-anchor" href="#what-you-just-learned" aria-label="Permalink to &quot;What you just learned&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Meaning</th></tr></thead><tbody><tr><td><code>sdd init</code></td><td>One-time project setup</td></tr><tr><td><code>sdd new</code></td><td>Start a piece of work</td></tr><tr><td><code>sdd status</code></td><td>Where am I?</td></tr><tr><td><code>sdd next</code></td><td>This step is done; go to the next</td></tr><tr><td><code>sdd complete</code></td><td>This piece of work is finished</td></tr></tbody></table><hr><h2 id="what-next" tabindex="-1">What next? <a class="header-anchor" href="#what-next" aria-label="Permalink to &quot;What next?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>I want to…</th><th>Go here</th></tr></thead><tbody><tr><td>Use the same loop every day</td><td><a href="./../guides/everyday-loop">Everyday loop</a></td></tr><tr><td>Turn the AI on after process steps</td><td><a href="./../guides/agents">AI agents setup</a></td></tr><tr><td>Ship a real feature</td><td><a href="./../guides/simple-feature">Simple feature</a></td></tr><tr><td>Start a product from one sentence</td><td><a href="./../guides/greenfield">Greenfield</a></td></tr></tbody></table>`,52)])])}const k=e(n,[["render",d]]);export{g as __pageData,k as default};
